const CountingInput = () => {
  const [value, setValue] = React.useState('');
  const [refCalls, setRefCalls] = React.useState(0);
  const slotRef = React.useRef<HTMLInputElement | null>(null);
  const countRef = React.useCallback((_node: HTMLInputElement | null) => {
    // A state update that never settles on its own, like the node bookkeeping
    // Slate/Plate perform inside ref callbacks.
    setRefCalls((count) => count + 1);
  }, []);

  return (
    <Slot ref={slotRef} onChange={(event) => setValue(event.target.value)}>
      <input data-ref-calls={refCalls} ref={countRef} value={value} />
    </Slot>
  );
};

